window.DEFIS = [{"day": 12, "title": "Le travail et la vie professionnelle", "prompt": "Présente ton travail et tes responsabilités.", "questions": ["Quelles sont tes principales responsabilités ?", "Quels types de tâches réalises-tu ?", "Quelles sont les difficultés que tu rencontres ?", "Comment organises-tu ton travail ?", "Quels sont tes objectifs professionnels ?"], "tip": "Intenta utilizar al menos 8 palabras y 3 expresiones del día.", "topic": "Día 12 · Le travail et la vie professionnelle"}, {"day": 13, "title": "La communication et les relations sociales", "prompt": "Parle de la communication au travail.", "questions": ["Est-ce que tu préfères communiquer par téléphone ou par e-mail ?", "Est-ce que tu trouves facile de t'exprimer en français ?", "As-tu déjà vécu un malentendu à cause de la langue ?", "Comment réagis-tu lorsqu'une personne n'est pas d'accord avec toi ?"], "tip": "Intenta utilizar al menos 8 palabras y 3 expresiones del día.", "topic": "Día 13 · La communication et les relations sociales"}, {"day": 14, "title": "Les voyages et les transports", "prompt": "Raconte un voyage que tu as particulièrement aimé.", "questions": ["Où es-tu allée ?", "Avec qui ?", "Qu'est-ce que tu as visité ?", "As-tu eu des imprévus ?", "Qu'est-ce qui t'a le plus marquée ?"], "tip": "Cuenta la historia en pasado: passé composé + imparfait.", "topic": "Día 14 · Les voyages et les transports"}, {"day": 15, "title": "Les émotions et la personnalité", "prompt": "Parle de la confiance en soi.", "questions": ["Est-ce que tu as confiance en toi ?", "Dans quelles situations hésites-tu ?", "Comment réagis-tu face aux critiques ?", "Qu'est-ce qui te permet de te sentir mieux ?", "Comment peut-on développer sa confiance en soi ?"], "tip": "Evita « bien, mal, content, triste »: usa el vocabulario preciso del día.", "topic": "Día 15 · Les émotions et la personnalité"}, {"day": 16, "title": "La technologie et les réseaux sociaux", "prompt": "Les nouvelles technologies facilitent-elles vraiment notre vie ?", "questions": ["Quels sont les avantages de la technologie ?", "Quels sont les inconvénients des réseaux sociaux ?", "Sommes-nous trop dépendants du téléphone ?", "Que penses-tu de la confidentialité sur Internet ?", "Comment la technologie a-t-elle changé ta vie professionnelle ?"], "tip": "Da tu opinión con matices: d'un côté… de l'autre…, cependant, en revanche.", "topic": "Día 16 · La technologie et les réseaux sociaux"}, {"day": 17, "title": "L'environnement et la société", "prompt": "Est-il encore possible de protéger l'environnement ?", "questions": ["Quels sont les principaux problèmes environnementaux ?", "Que peuvent faire les citoyens ?", "Quelle responsabilité ont les entreprises ?", "Est-ce que les gouvernements font suffisamment d'efforts ?", "Penses-tu que nos habitudes de consommation doivent changer ?"], "tip": "Estructura: introducción, dos argumentos, conclusión.", "topic": "Día 17 · L'environnement et la société"}, {"day": 18, "title": "Le temps et l'organisation", "prompt": "Comment organises-tu ton temps entre le travail et la vie personnelle ?", "questions": ["Comment organises-tu tes journées ?", "Est-ce que tu as beaucoup de responsabilités ?", "Comment gères-tu les imprévus ?", "Est-ce que tu arrives à trouver du temps pour toi ?", "Quelles sont tes astuces pour être plus efficace ?"], "tip": "Usa expresiones como « être débordée », « s'y prendre à l'avance », « établir des priorités ».", "topic": "Día 18 · Le temps et l'organisation"}, {"day": 19, "title": "Les problèmes et les solutions", "prompt": "Raconte un problème que tu as rencontré au travail et explique comment tu l'as résolu.", "questions": ["Quel était le problème ?", "Comment l'as-tu identifié ?", "Quelles étaient les causes ?", "Quelles solutions as-tu envisagées ?", "Quel a été le résultat ?"], "tip": "Usa vocabulario técnico y el passé composé.", "topic": "Día 19 · Les problèmes et les solutions"}, {"day": 20, "title": "Les relations humaines et les conflits", "prompt": "Est-il important d'avoir de bonnes relations avec ses collègues ?", "questions": ["Pourquoi la confiance est-elle importante ?", "Comment éviter les conflits ?", "Est-il nécessaire de partager les mêmes opinions ?", "Comment réagir face à un désaccord ?", "Est-ce qu'il est parfois nécessaire de faire des compromis ?"], "tip": "Intenta usar « trouver un terrain d'entente » y « être sur la même longueur d'onde ».", "topic": "Día 20 · Les relations humaines et les conflits"}, {"day": 21, "title": "Les changements et les expériences de vie", "prompt": "Parle d'un changement important dans ta vie.", "questions": ["Quel changement a eu le plus d'impact sur ta vie ?", "Pourquoi as-tu pris cette décision ?", "Quelles difficultés as-tu rencontrées ?", "Qu'as-tu appris de cette expérience ?", "Comment as-tu évolué depuis ?"], "tip": "Puedes hablar de tu vida en Suiza o de aprender francés. Usa « avec le recul » y « franchir un cap ».", "topic": "Día 21 · Les changements et les expériences de vie"}];
